output:
Шаг 1. Данные: четыре товара
[
  {
    "title": "Кружка",
    "price": 400,
    "labels": [
      "стекло"
    ]
  },
  {
    "title": "Сенча",
    "price": 900,
    "labels": [
      "хит"
    ]
  },
  {
    "title": "Пуэр",
    "price": 1500,
    "labels": null
  },
  {
    "title": "Чайник",
    "price": 2500,
    "labels": [
      "хит",
      "стекло"
    ]
  }
]

Шаг 2. Сравнения: ne, gt, gte, lt, lte
{
  "ne(900)": [
    "Кружка",
    "Пуэр",
    "Чайник"
  ],
  "gt(1500)": [
    "Чайник"
  ],
  "gte(1500)": [
    "Пуэр",
    "Чайник"
  ],
  "lt(900)": [
    "Кружка"
  ],
  "lte(900)": [
    "Кружка",
    "Сенча"
  ]
}

Шаг 3. Диапазон и список: between, inList
{
  "between(500, 2000)": [
    "Пуэр",
    "Сенча"
  ],
  "inList(['K-1', 'M-1'])": [
    "Кружка",
    "Чайник"
  ]
}

Шаг 4. Текст: like, ilike, starts, ends
{
  "like('%а%')": [
    "Кружка",
    "Сенча",
    "Чайник"
  ],
  "ilike('ч%')": [
    "Чайник"
  ],
  "starts('T-')": [
    "Пуэр",
    "Сенча"
  ],
  "ends('-1')": [
    "Кружка",
    "Чайник"
  ]
}

Шаг 5. Массивы: has, hasAny, hasAll
{
  "has('хит')": [
    "Сенча",
    "Чайник"
  ],
  "hasAny(['стекло', 'акция'])": [
    "Кружка",
    "Чайник"
  ],
  "hasAll(['хит', 'стекло'])": [
    "Чайник"
  ]
}

Шаг 6. Есть ли поле: exists, isNull
{
  "labels: exists(true)": [
    "Кружка",
    "Сенча",
    "Чайник"
  ],
  "labels: exists(false)": [
    "Пуэр"
  ],
  "specs: isNull()": [
    "Кружка",
    "Пуэр",
    "Сенча"
  ]
}

Шаг 7. Отрицание и «или»: not, or
{
  "not('paid')": [
    "A-1"
  ],
  "not(gte(1000))": [
    "Кружка",
    "Сенча"
  ],
  "or({ sku: 'K-1' }, { price: lt(500) })": [
    "Кружка",
    "Чайник"
  ]
}

Шаг 8. Фильтр по концу и корневые категории
{
  "товары «Лютика»": [
    "Кружка"
  ],
  "корневые категории": [
    "Посуда",
    "Чай"
  ]
}

Шаг 9. Без приведения типов
{
  "price: 900": [
    "Сенча"
  ],
  "price: '900'": []
}

Шаг 10. Оператор — это объект-маркер
{
  "isOp(gt(1))": true,
  "isOp(1)": false
}
